<?php declare(strict_types=1); ?>
<section class="dwf-card" data-voucher-mail-history><h3><?= e($vmI('Versandverlauf')) ?></h3><?php $mnSearch('history','Versandvorgänge durchsuchen'); ?>
<form method="get" class="voucher-manager-search"><?php foreach($mnBase as$field=>$value)if(!in_array($field,['voucher_mail_state','voucher_mail_history_page'],true))echo hidden($field,$value);echo hidden('voucher_mail_history_page','1');$mnFilter=$mnState['query']['voucher_mail_state']??'all';?><label><?= e($vmI('Versandstand')) ?><select class="form-control" name="voucher_mail_state"><?php if(!array_key_exists($mnFilter,['all'=>'']+$mnStatus)):?><option selected value="<?= e($mnFilter) ?>"><?= e($vmI('Versandstand auswählen.')) ?></option><?php endif ?><option value="all" <?= $mnFilter==='all'?'selected':'' ?>><?= e($vmI('Alle Versandstände')) ?></option><?php foreach($mnStatus as$mnValue=>$mnLabel):?><option value="<?= e($mnValue) ?>" <?= $mnFilter===$mnValue?'selected':'' ?>><?= e($vmI($mnLabel)) ?></option><?php endforeach ?></select></label><button class="btn btn-outline theme-secondary dwf-button"><?= e($vmI('Anzeigen')) ?></button></form>
<?php if(isset($mnState['errors']['deliveries'])):?><p class="dwf-alert dwf-error" role="alert"><?= e($vmI($mnState['errors']['deliveries'])) ?></p><?php endif;echo $mnPager('history',$mnState['deliveries'],'Gutschein-Mail-Verlaufsseiten'); ?>
<?php foreach($mnState['deliveries']['rows']??[]as$mnDelivery):?><article class="personal-voucher-event" data-voucher-mail-delivery><h4><?= e($mnDelivery['original_name']??$vmI('Name nicht gespeichert.')) ?></h4><?php if($mnDelivery['original_name']!==$mnDelivery['current_name']):?><p><?= e($vmI('Aktueller Profilname')) ?>: <?= e($mnDelivery['current_name']) ?></p><?php endif ?><p><?= e($mnDelivery['email']) ?> · <?= e($vmI($mnStatus[$mnDelivery['state']])) ?></p><p><?= e($vmDate($mnDelivery['updated_at'])) ?></p><a class="btn btn-outline theme-secondary dwf-button" href="<?= e($mnUrl(['voucher_mail_section'=>'history','voucher_mail_delivery'=>$mnDelivery['id']])) ?>"><?= e($vmI('Ursprünglichen Versandvorgang öffnen')) ?></a></article><?php endforeach ?>
<?php if($mnState['deliveries']!==null&&!$mnState['deliveries']['rows']):?><p><?= e($vmI('Keine passenden Versandvorgänge.')) ?></p><?php endif ?><?= $mnPager('history',$mnState['deliveries'],'Gutschein-Mail-Verlaufsseiten') ?>
</section>
<?php if($mnState['original']!==null):$mnOriginal=$mnState['original'];$mnOriginalRow=$mnOriginal['delivery'];$mnOriginalData=$mnOriginal['snapshot'];$mnOriginalMessage=\Kulturhus\Verein\EventVoucherMail::message($mnOriginalData);$mnEnding=$mnDraft!==null&&$mnDraft['action']==='event-voucher-mail-cancel';$mnCanEnd=in_array($mnOriginalRow['state'],['pending','uncertain','blocked'],true);$mnEndingChanged=$mnEnding&&(($mnDraft['values']['expected_state']??'')!==$mnOriginalRow['state']||($mnDraft['values']['expected_at']??'')!==$mnOriginalRow['updated_at']||($mnDraft['values']['expected_fingerprint']??'')!==$mnOriginalRow['fingerprint']);?>
<section class="dwf-card" data-voucher-mail-original><h3><?= e($vmI('Versandvorschau')) ?></h3><p><?= e($vmI('Diese gespeicherten Angaben sind kein aktueller Gutscheinstand. Hier werden keine aktiven QR-Codes angeboten.')) ?></p><h4><?= e($mnOriginalData['person']['name']) ?></h4><p><?= e($mnOriginalData['person']['email']) ?></p><p><?= e($mnOriginalData['title']) ?> · <?= e($vmDate($mnOriginalData['date'])) ?></p><p><strong><?= e($vmI('Betreff:')) ?></strong> <?= e($mnOriginalMessage['subject']) ?></p><div class="voucher-manager-original"><?= e($mnOriginalMessage['intro']) ?></div><details><summary><?= e($vmI('Vollständigen ursprünglichen Text lesen')) ?></summary><div class="voucher-manager-original"><?= e($mnOriginalData['text']) ?></div></details>
<p><a download class="btn btn-outline theme-secondary dwf-button" href="<?= e(url(['voucher_mail_original'=>$mnOriginalRow['id'],'voucher_event'=>$vmEventId])) ?>"><?= e($vmI('Ursprüngliche Versandvorschau als JSON herunterladen')) ?></a></p><p><?= e($vmI('Die damaligen PDF-Dateibytes wurden nicht gespeichert. Die JSON-Datei enthält die tatsächlich gespeicherten ursprünglichen Versandangaben.')) ?></p>
<section data-voucher-mail-current-status><h4><?= e($vmI('Aktueller Versandstand')) ?></h4><p><?= e($vmI($mnStatus[$mnOriginalRow['state']])) ?> · <?= e($vmDate($mnOriginalRow['updated_at'])) ?></p><p><?= e($vmI($mnOriginalRow['error'])) ?></p></section>
<?php if($mnEnding):?><form method="post" data-voucher-mail-ending data-confirm-other-drafts <?= $vmState['proposal_restored']?'data-unsaved-changes':'' ?>><?= $mnForm($mnDraft) ?><p><?= e($vmI('Ursprünglich geprüfter Versandstand')) ?>: <?= e($vmI($mnStatus[$mnDraft['values']['expected_state']]??$mnDraft['values']['expected_state'])) ?> · <?= e($vmDate($mnDraft['values']['expected_at'])) ?></p>
<?php if($mnEndingChanged):?><p class="dwf-alert" role="alert"><?= e($vmI('Versandstand inzwischen geändert. Bitte den aktuellen Vorgang prüfen.')) ?></p><?php endif ?>
<p><?= e($vmI('Bei unklarer Zustellung zuerst beim Mitglied nachfragen. Beenden versendet keine neue Mail und verändert keine Gutscheine.')) ?></p><label class="voucher-manager-person"><input type="checkbox" name="voucher_mail_confirm" value="1" required <?= ($mnDraft['values']['voucher_mail_confirm']??'')==='1'?'checked':'' ?>><span><?= e($vmI('Ich habe den Versandstand geprüft und möchte genau diesen Vorgang beenden.')) ?></span></label><button class="btn btn-outline theme-secondary dwf-button" <?= $mnCanEnd&&!$mnEndingChanged?'':'disabled' ?>><?= e($vmI('Versandvorgang beenden')) ?></button><?php $mnReview($mnDraft); ?></form><?php endif ?>
<details><summary><?= e($vmI('Vorgangskennung')) ?></summary><p class="voucher-manager-original"><?= e($mnOriginalRow['id']) ?></p></details>
</section><?php endif ?>
